parameters.jsCode:
const cfg = $('Config Ready').first().json;
function pick(name) { try { return $(name).first().json; } catch(e) { return null; } }
const before = pick('GET Automation Status');
const afterRun = pick('POST Automation Run');
const polled = pick('Poll Status') || before;
const mode = cfg.mode;
const modeStatus = polled?.status?.byMode?.[mode] || polled?.byMode?.[mode] || {};
const profile = (pick('GET Automation Config') || {}).profiles?.[mode] || {};
return [{
  json: {
    stage: '08-drive-image-cuts',
    mode,
    actuallyRan: !!cfg.actuallyRun,
    runAccepted: afterRun?.ok === true,
    runMessage: afterRun?.message || afterRun?.error || null,
    isRunning: !!modeStatus.isRunning,
    lastSummary: modeStatus.lastSummary || null,
    lastError: modeStatus.lastError || null,
    progress: modeStatus.progress || profile.automationProgress || null,
    driveConnection: (pick('GET Automation Config') || {}).driveConnection || null,
    folders: {
      inputFolderId: profile.inputFolderId || '',
      outputFolderId: profile.outputFolderId || '',
      sourceDoneFolderId: profile.sourceDoneFolderId || ''
    },
    safetyNote: cfg.actuallyRun
      ? '즉시 실행 요청됨. Drive 입력 폴더 이미지에 대해 컷 생성이 돌아갈 수 있습니다.'
      : 'dry 조회만 수행. actuallyRun=true 로 바꿔야 실제 Drive 자동화가 시작됩니다.',
    nextStep: 'output-images 확인 또는 브라우저 자동화 탭 검수'
  }
}];
